import java.util.*;

/**
 * Exercises Field.adjacentLocations across every cell of a grid (corners,
 * edges, interior) with the seeded shared RNG, hashing the full sequence of
 * shuffled neighbour lists. Identical hashes between the baseline and
 * refactored builds prove the insertion order (and therefore the shuffle
 * result) is unchanged at every position.
 */
public class FieldProbe {
    public static void main(String[] a) {
        int depth = 12, width = 9;
        Field f = new Field(depth, width);
        Randomizer.reset();
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < depth; r++) {
            for (int c = 0; c < width; c++) {
                List<Location> adj = f.adjacentLocations(new Location(r, c));
                sb.append(r).append(',').append(c).append("->");
                for (Location l : adj) sb.append(l.toString()).append(';');
                sb.append('\n');
            }
        }
        System.out.println("hash=" + sb.toString().hashCode() + " len=" + sb.length());
    }
}

